async function embed(texts, inputType) {
  const res = await fetch("https://api.voyageai.com/v1/embeddings", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: "Bearer " + process.env.VOYAGE_API_KEY,
    },
    body: JSON.stringify({ model: "voyage-4", input: texts, input_type: inputType }),
  });
  const json = await res.json();
  return json.data.map((d) => d.embedding); // по одному вектору на текст
}

const chunks = ["Ошибка 4017: истёк токен доступа.", "Коды ошибок API."];
const docVectors = await embed(chunks, "document");               // один раз, при индексации
const [queryVector] = await embed(["что значит 4017?"], "query"); // на каждый вопрос

CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE chunks (
  id        bigserial PRIMARY KEY,
  content   text,
  embedding vector(3)          -- в жизни vector(1024) или vector(1536)
);
CREATE INDEX ON chunks USING hnsw (embedding vector_cosine_ops);

INSERT INTO chunks (content, embedding) VALUES
  ('как вернуть товар',      '[0.9, 0.1, 0.0]'),
  ('возврат денег за заказ', '[0.8, 0.3, 0.1]'),
  ('доставка по России',     '[0.1, 0.9, 0.2]');

SELECT content,
       embedding <=> '[1, 0.2, 0]'       AS cosine_distance,
       1 - (embedding <=> '[1, 0.2, 0]') AS cosine_similarity
FROM chunks
ORDER BY embedding <=> '[1, 0.2, 0]'
LIMIT 2;
-- как вернуть товар      | 0.004 | 0.996
-- возврат денег за заказ | 0.020 | 0.980

const docs = {
  A: "Ошибка 4017: истёк токен доступа. Войдите заново.",
  B: "Ошибка 4071: превышен лимит запросов. Подождите минуту.",
  C: "Коды ошибок API и что они означают.",
};
const tok = (s) => s.toLowerCase().match(/[\p{L}\p{N}]+/gu);
const k1 = 1.2, b = 0.75; // значения по умолчанию в Elasticsearch
const ids = Object.keys(docs);
const toks = Object.fromEntries(ids.map((id) => [id, tok(docs[id])]));
const N = ids.length;
const avgdl = ids.reduce((s, id) => s + toks[id].length, 0) / N;

function bm25(query, id) {
  const d = toks[id];
  let score = 0;
  for (const term of tok(query)) {
    const n = ids.filter((x) => toks[x].includes(term)).length; // в скольких документах есть слово
    if (n === 0) continue;
    const idf = Math.log(1 + (N - n + 0.5) / (n + 0.5));        // редкое слово весит больше
    const tf = d.filter((t) => t === term).length;               // сколько раз слово в документе
    score += idf * (tf * (k1 + 1)) / (tf + k1 * (1 - b + b * d.length / avgdl));
  }
  return score;
}
for (const id of ids) console.log(id, bm25("ошибка 4017", id).toFixed(3));
// A 1.451   B 0.470   C 0.000

const vectorRanks = ["B", "A", "C"]; // семантика: 4071 и 4017 для неё почти одно и то же
const bm25Ranks   = ["A", "B"];      // BM25: точное "4017" выигрывает, C по словам не нашёлся
const K = 60;                          // rank_constant по умолчанию в Elasticsearch
const scores = {};
for (const list of [vectorRanks, bm25Ranks])
  list.forEach((id, i) => { scores[id] = (scores[id] ?? 0) + 1 / (K + i + 1); });
// B 0.0325   A 0.0325   C 0.0159

